// Переклад вбудованих рецептів (fr). Ключ — id з recipes-data.js.
export default {
  'oat-protein': { name: 'Porridge protéiné à la banane', ing: ['Flocons d’avoine — 60 g', 'Lait demi-écrémé — 200 ml', 'Protéine vanille — 1 dosette (30 g)', 'Banane — ½', 'Cannelle — 1 pincée'], steps: ['Verse le lait sur les flocons et fais cuire 3 à 4 minutes à feu doux.', 'Retire du feu, laisse tiédir un peu et incorpore la protéine pour qu’elle ne coagule pas.', 'Dispose la banane en rondelles dessus et saupoudre de cannelle.'] },
  'omelette-spinach': { name: 'Omelette aux épinards et à la feta', ing: ['Œufs — 2', 'Blancs d’œufs — 2', 'Épinards — 1 poignée (30 g)', 'Feta — 30 g', 'Sel, poivre'], steps: ['Bats les œufs avec les blancs, sale et poivre.', 'Fais revenir les épinards 1 minute dans une poêle antiadhésive.', 'Verse les œufs, parsème de feta, couvre et fais cuire 4 à 5 minutes à feu doux.'] },
  'syrniki-oven': { name: 'Syrniki au four sans farine (galettes de fromage blanc)', ing: ['Fromage blanc 5 % — 250 g', 'Œuf — 1', 'Farine d’avoine ou flocons mixés — 30 g', 'Édulcorant ou miel — 1 c. à c.', 'Vanille en poudre — 1 pincée'], steps: ['Écrase le fromage blanc à la fourchette, ajoute l’œuf, la farine d’avoine, l’édulcorant et la vanille.', 'Façonne 6 à 8 galettes et dépose-les sur du papier cuisson.', 'Fais cuire 20 minutes à 180 °C en les retournant à mi-cuisson.'] },
  'toast-avocado-egg': { name: 'Toast à l’avocat et à l’œuf poché', ing: ['Pain complet — 2 tranches', 'Avocat — ½', 'Œufs — 2', 'Jus de citron — 1 c. à c.', 'Sel, flocons de piment'], steps: ['Fais griller le pain au grille-pain ou dans une poêle sèche.', 'Écrase l’avocat avec le jus de citron et le sel, puis étale-le sur les toasts.', 'Poche les œufs 3 minutes dans l’eau frémissante et dépose-les dessus.'] },
  'greek-yogurt-bowl': { name: 'Bol de yaourt grec, fruits rouges et granola', ing: ['Yaourt grec 2 % — 200 g', 'Fruits rouges (frais ou surgelés) — 80 g', 'Granola sans sucre — 25 g', 'Miel — 1 c. à c.'], steps: ['Verse le yaourt dans un bol.', 'Ajoute les fruits rouges et le granola.', 'Arrose de miel et mange aussitôt, tant que le granola est croustillant.'] },
  'egg-muffins': { name: 'Muffins aux œufs et aux légumes (2 pièces)', ing: ['Œufs — 3', 'Poivron — ½', 'Tomates cerises — 4', 'Fromage à pâte dure — 20 g', 'Herbes, sel'], steps: ['Coupe les légumes en petits dés et répartis-les dans des moules à muffins.', 'Verse dessus les œufs battus et salés, parsème de fromage.', 'Fais cuire 18 à 20 minutes à 180 °C. Ils se conservent 3 jours au réfrigérateur.'] },
  'buckwheat-milk-egg': { name: 'Sarrasin aux œufs et au fromage', ing: ['Sarrasin — 80 g (cru)', 'Œufs — 2', 'Fromage à pâte dure — 30 g', 'Beurre — 5 g', 'Ciboule'], steps: ['Fais cuire le sarrasin (1 volume pour 2 d’eau, 15 minutes).', 'Fais cuire les œufs au plat ou mollets.', 'Mélange le sarrasin avec le beurre, ajoute les œufs, râpe le fromage et parsème de ciboule.'] },
  'pancakes-protein': { name: 'Pancakes protéinés', ing: ['Farine d’avoine — 50 g', 'Protéine — 1 dosette (30 g)', 'Œuf — 1', 'Lait — 100 ml', 'Levure chimique — ½ c. à c.', 'Fruits rouges pour servir — 50 g'], steps: ['Mélange tous les ingrédients pour obtenir une pâte épaisse.', 'Fais cuire de petits pancakes dans une poêle antiadhésive sèche, 1 à 2 minutes de chaque côté.', 'Sers avec des fruits rouges ou une cuillère de yaourt.'] },
  'chicken-rice-broccoli': { name: 'Poulet, riz et brocoli', ing: ['Blanc de poulet — 180 g', 'Riz — 70 g (cru)', 'Brocoli — 150 g', 'Huile d’olive — 1 c. à c.', 'Sauce soja, ail, paprika'], steps: ['Fais cuire le riz.', 'Coupe le poulet en morceaux et fais-le mariner 10 minutes dans la sauce soja avec l’ail et le paprika.', 'Fais dorer le poulet à l’huile 6 à 8 minutes, ajoute le brocoli et laisse mijoter à couvert encore 5 minutes.', 'Sers avec le riz. Pratique à préparer d’un coup pour 3 à 4 jours.'] },
  'turkey-bolognese': { name: 'Pâtes bolognaise à la dinde', ing: ['Dinde hachée — 150 g', 'Pâtes de blé dur — 90 g (crues)', 'Tomates concassées — 200 g', 'Oignon — ½', 'Ail — 1 gousse', 'Parmesan — 10 g'], steps: ['Fais cuire les pâtes al dente.', 'Fais revenir l’oignon et l’ail, ajoute la viande et fais-la dorer 5 minutes.', 'Ajoute les tomates, le sel et le basilic, puis laisse mijoter 10 minutes.', 'Mélange avec les pâtes et parsème de parmesan.'] },
  'salmon-potato': { name: 'Saumon et pommes de terre rôties', ing: ['Filet de saumon — 150 g', 'Pommes de terre — 250 g', 'Huile d’olive — 1 c. à c.', 'Citron — ¼', 'Romarin, sel, poivre'], steps: ['Coupe les pommes de terre en quartiers et mélange-les avec l’huile, le sel et le romarin.', 'Fais-les rôtir 15 minutes à 200 °C.', 'Ajoute le saumon sur la plaque, arrose de citron et enfourne encore 12 minutes.'] },
  'beef-buckwheat': { name: 'Bœuf mijoté au sarrasin', ing: ['Bœuf — 160 g', 'Sarrasin — 80 g (cru)', 'Carotte — 1', 'Oignon — ½', 'Concentré de tomate — 1 c. à s.', 'Laurier, poivre'], steps: ['Coupe le bœuf en cubes et fais-le saisir jusqu’à obtenir une belle croûte.', 'Ajoute l’oignon, la carotte et le concentré de tomate, couvre d’eau et laisse mijoter 45 minutes.', 'Pendant ce temps, fais cuire le sarrasin et sers-le avec la viande.'] },
  'tuna-salad': { name: 'Salade de thon et œuf', ing: ['Thon au naturel — 1 boîte (120 g)', 'Œuf — 1', 'Concombre — 1', 'Tomates cerises — 6', 'Feuilles de salade — 1 poignée', 'Huile d’olive — 1 c. à c., jus de citron'], steps: ['Fais cuire l’œuf dur et coupe-le en morceaux.', 'Coupe le concombre et les tomates cerises, déchire la salade.', 'Ajoute le thon et assaisonne avec l’huile et le jus de citron.'] },
  'chicken-wrap': { name: 'Wrap au poulet et aux légumes', ing: ['Galette de blé complet — 1', 'Blanc de poulet — 120 g', 'Yaourt grec — 2 c. à s.', 'Concombre, tomate, salade', 'Ail, sel, paprika'], steps: ['Fais dorer le poulet coupé en lamelles avec le paprika.', 'Mélange le yaourt avec l’ail pour faire la sauce.', 'Étale la sauce sur la galette, dépose le poulet et les légumes, puis roule bien serré. Tu peux le faire dorer 1 minute à la poêle.'] },
  'turkey-meatballs': { name: 'Boulettes de dinde à la sauce tomate', ing: ['Dinde hachée — 180 g', 'Flocons d’avoine — 20 g', 'Œuf — ½', 'Sauce tomate — 150 g', 'Oignon, ail, herbes'], steps: ['Mélange la viande avec les flocons, l’œuf, l’oignon et le sel.', 'Façonne des boulettes et dépose-les dans un plat.', 'Nappe de sauce tomate et fais cuire 20 minutes à 190 °C.'] },
  'shrimp-stirfry': { name: 'Crevettes sautées au wok', ing: ['Crevettes décortiquées — 180 g', 'Mélange de légumes pour wok — 200 g', 'Nouilles de riz — 50 g (crues)', 'Sauce soja — 1 c. à s.', 'Gingembre, ail, sésame'], steps: ['Fais tremper les nouilles dans l’eau bouillante 5 minutes.', 'Fais revenir l’ail et le gingembre, ajoute les légumes et fais sauter 3 minutes à feu vif.', 'Ajoute les crevettes, la sauce soja et les nouilles, mélange 2 minutes. Parsème de sésame.'] },
  'lentil-soup': { name: 'Soupe de lentilles corail', ing: ['Lentilles corail — 70 g', 'Carotte — 1', 'Oignon — ½', 'Concentré de tomate — 1 c. à s.', 'Cumin, paprika, citron'], steps: ['Fais revenir l’oignon et la carotte, ajoute les épices et le concentré de tomate.', 'Ajoute les lentilles rincées et 600 ml d’eau, puis fais cuire 20 minutes.', 'Mixe, sale et sers avec un filet de citron.'] },
  'chicken-curry': { name: 'Poulet au curry et riz', ing: ['Haut de cuisse de poulet sans peau — 170 g', 'Riz basmati — 80 g (cru)', 'Lait de coco allégé — 80 ml', 'Pâte ou poudre de curry — 1 c. à s.', 'Oignon, ail, épinards'], steps: ['Fais cuire le riz.', 'Fais revenir l’oignon, l’ail et le curry 1 minute, puis ajoute le poulet coupé en morceaux.', 'Verse le lait de coco, laisse mijoter 12 minutes et ajoute les épinards en fin de cuisson.'] },
  'cod-veggies': { name: 'Cabillaud et légumes en papillote', ing: ['Filet de cabillaud — 200 g', 'Courgette — ½', 'Tomate — 1', 'Citron — 2 rondelles', 'Huile d’olive — 1 c. à c., aneth'], steps: ['Dépose les légumes sur du papier cuisson, puis le poisson, le citron et l’aneth.', 'Arrose d’huile, sale et referme bien la papillote.', 'Fais cuire 18 minutes à 200 °C.'] },
  'pork-loin-sweetpotato': { name: 'Filet mignon de porc et patate douce', ing: ['Filet mignon de porc — 160 g', 'Patate douce — 300 g', 'Moutarde — 1 c. à c.', 'Huile d’olive — 1 c. à c.', 'Thym, sel, poivre'], steps: ['Coupe la patate douce en cubes, mélange-la avec l’huile et fais-la rôtir 20 minutes à 200 °C.', 'Enrobe le filet de moutarde, de sel et de thym, puis fais-le dorer 2 minutes de chaque côté.', 'Termine la cuisson de la viande au four avec la patate douce, encore 10 minutes.'] },
  'cottage-cheese-berries': { name: 'Fromage blanc aux fruits rouges', ing: ['Fromage blanc 2 % — 180 g', 'Fraises ou autres fruits rouges — 80 g', 'Édulcorant ou miel — selon le goût'], steps: ['Verse le fromage blanc dans un bol.', 'Ajoute les fruits rouges et l’édulcorant, mélange. C’est prêt.'] },
  'protein-balls': { name: 'Boules protéinées au beurre de cacahuète (3 pièces)', ing: ['Flocons d’avoine — 30 g', 'Beurre de cacahuète — 1 c. à s.', 'Protéine chocolat — ½ dosette', 'Miel — 1 c. à c.', 'Cacao pour rouler les boules'], steps: ['Mélange les flocons, le beurre de cacahuète, la protéine et le miel jusqu’à obtenir une pâte collante (ajoute une cuillère d’eau si elle est trop sèche).', 'Forme des boules et roule-les dans le cacao.', 'Laisse prendre 20 minutes au réfrigérateur.'] },
  'hummus-veggies': { name: 'Houmous et bâtonnets de légumes', ing: ['Houmous — 70 g', 'Carotte — 1', 'Concombre — 1', 'Poivron — ½'], steps: ['Coupe les légumes en bâtonnets.', 'Sers avec le houmous. Pratique à emporter dans une boîte.'] },
  'eggs-boiled-snack': { name: 'Œufs durs et concombre', ing: ['Œufs — 2', 'Concombre — 1', 'Sel, poivre'], steps: ['Fais cuire les œufs 9 minutes et refroidis-les dans l’eau froide.', 'Sers avec le concombre en rondelles. La collation protéinée la plus simple.'] },
  'rice-cakes-pb-banana': { name: 'Galettes de riz, beurre de cacahuète et banane', ing: ['Galettes de riz — 3', 'Beurre de cacahuète — 1,5 c. à s.', 'Banane — 1'], steps: ['Tartine les galettes de beurre de cacahuète.', 'Dépose dessus des rondelles de banane. Idéal une heure avant l’entraînement.'] },
  'chicken-nuggets-oven': { name: 'Nuggets de poulet au four', ing: ['Blanc de poulet — 180 g', 'Œuf — 1', 'Corn flakes sans sucre — 30 g', 'Paprika, ail, sel'], steps: ['Coupe le poulet en morceaux, sale et poivre.', 'Trempe-les dans l’œuf battu, puis roule-les dans les corn flakes écrasés mélangés au paprika.', 'Fais cuire 15 minutes à 200 °C.'] },
  'shake-mass': { name: 'Shake pour prendre de la masse', ing: ['Lait entier — 300 ml', 'Banane — 1', 'Flocons d’avoine — 40 g', 'Protéine — 1 dosette', 'Beurre de cacahuète — 1 c. à s.'], steps: ['Mets tous les ingrédients dans le blender.', 'Mixe 30 à 40 secondes jusqu’à obtenir une texture lisse. À boire après l’entraînement ou entre les repas.'] },
  'shake-green': { name: 'Smoothie vert protéiné', ing: ['Eau ou lait d’amande — 250 ml', 'Épinards — 1 poignée', 'Pomme — ½', 'Protéine vanille — 1 dosette', 'Glaçons — quelques-uns'], steps: ['Mets tous les ingrédients dans le blender.', 'Mixe jusqu’à obtenir une texture lisse et bois aussitôt.'] },
  'cheesecake-protein': { name: 'Cheesecake protéiné (1 part sur 4)', ing: ['Fromage blanc 2 % — 400 g', 'Yaourt grec — 150 g', 'Œufs — 2', 'Protéine vanille — 30 g', 'Maïzena — 1 c. à s.', 'Édulcorant'], steps: ['Mixe tout au blender jusqu’à obtenir une préparation lisse.', 'Verse dans un moule chemisé de papier cuisson.', 'Fais cuire 40 minutes à 160 °C, laisse refroidir dans le four, puis mets au réfrigérateur toute la nuit.'] },
  'chia-pudding': { name: 'Pudding de chia protéiné', ing: ['Graines de chia — 25 g', 'Lait — 150 ml', 'Protéine — ½ dosette', 'Fruits rouges ou mangue — 50 g'], steps: ['Mélange le chia, le lait et la protéine.', 'Laisse au réfrigérateur au moins 3 heures ou toute la nuit.', 'Sers avec des fruits rouges ou de la mangue.'] },
  'baked-oatmeal-apple': { name: 'Porridge d’avoine au four aux pommes', ing: ['Flocons d’avoine — 50 g', 'Pomme — 100 g (1 petite)', 'Œuf — 1', 'Lait — 100 ml', 'Cannelle — ½ c. à c.', 'Levure chimique — ½ c. à c.'], steps: ['Mélange les flocons d’avoine, l’œuf, le lait, la cannelle et la levure.', 'Ajoute la pomme coupée en dés et verse la préparation dans un ramequin.', 'Fais cuire 20 à 25 minutes à 180 °C jusqu’à ce que le dessus soit doré.'] },
  'cottage-banana-pancakes': { name: 'Pancakes au fromage blanc et à la banane', ing: ['Fromage blanc 5 % — 200 g', 'Banane — 1 (120 g)', 'Œuf — 1', 'Farine d’avoine — 40 g', 'Miel — 1 c. à c.'], steps: ['Écrase le fromage blanc avec la banane à la fourchette, puis ajoute l’œuf et la farine d’avoine.', 'Fais cuire de petits pancakes dans une poêle antiadhésive sèche, 2 à 3 minutes de chaque côté.', 'Sers avec une cuillerée de miel par-dessus.'] },
  'buckwheat-kefir-egg': { name: 'Sarrasin au képhir, à l’œuf et au concombre', ing: ['Sarrasin — 50 g (cru)', 'Képhir 1 % — 250 ml', 'Œuf — 1', 'Concombre — 100 g', 'Aneth, sel'], steps: ['Fais cuire le sarrasin (1 volume pour 2 d’eau, 15 minutes) et l’œuf dur.', 'Coupe le concombre et l’œuf, et hache l’aneth.', 'Mets le sarrasin dans un bol, ajoute le concombre et l’œuf, verse le képhir et parsème d’aneth.'] },
  'shakshuka-bread': { name: 'Shakshuka avec du pain complet', ing: ['Œufs — 3', 'Tomates au naturel — 200 g', 'Poivron — 100 g', 'Oignon — 40 g', 'Huile d’olive — 1 c. à c.', 'Pain complet — 1 tranche', 'Paprika, sel'], steps: ['Fais revenir l’oignon et le poivron coupé dans l’huile pendant 3 minutes.', 'Ajoute les tomates, le paprika et le sel, puis laisse mijoter 7 minutes.', 'Creuse des puits dans la sauce, casse les œufs, couvre et fais cuire 5 minutes. Sers avec le pain.'] },
  'cottage-cheese-bake-apple': { name: 'Gratin de fromage blanc aux pommes', ing: ['Fromage blanc 2 % — 200 g', 'Œuf — 1', 'Farine d’avoine — 20 g', 'Pomme — 100 g', 'Édulcorant, vanille'], steps: ['Mélange le fromage blanc avec l’œuf, la farine d’avoine, l’édulcorant et la vanille.', 'Ajoute la pomme coupée en petits dés et verse dans un petit moule.', 'Fais cuire 30 minutes à 180 °C, laisse refroidir un peu et coupe en parts.'] },
  'breakfast-burrito': { name: 'Burrito du petit-déjeuner aux œufs et aux haricots', ing: ['Tortilla complète — 1 (60 g)', 'Œufs — 2', 'Haricots en conserve — 60 g', 'Fromage à pâte dure — 25 g', 'Avocat — 40 g', 'Salsa — 2 c. à s.'], steps: ['Bats les œufs et fais-les cuire avec du sel en remuant, jusqu’à ce qu’ils soient moelleux.', 'Réchauffe la tortilla et garnis-la des œufs, des haricots, du fromage, de l’avocat et de la salsa.', 'Replie bien les côtés comme une enveloppe et fais dorer 1 minute dans une poêle sèche.'] },
  'millet-pumpkin': { name: 'Bouillie de millet à la courge', ing: ['Millet — 60 g (cru)', 'Courge — 150 g', 'Lait 1,5 % — 150 ml', 'Beurre — 5 g', 'Miel — 1 c. à c.'], steps: ['Rince le millet à l’eau bouillante et mets-le dans une casserole avec la courge coupée.', 'Verse 200 ml d’eau et le lait, puis fais cuire 20 minutes à feu doux.', 'Ajoute le beurre et le miel, couvre et laisse reposer 5 minutes.'] },
  'egg-cheese-sandwich': { name: 'Sandwich à l’œuf, au fromage et au jambon de dinde', ing: ['Pain complet — 3 tranches', 'Œufs — 2', 'Jambon de dinde — 40 g', 'Fromage à pâte dure — 30 g', 'Tomate — 50 g'], steps: ['Fais griller le pain au grille-pain.', 'Fais cuire les œufs dans une poêle antiadhésive sans matière grasse.', 'Assemble le sandwich : pain, jambon, fromage, œuf, tomate. Presse et coupe en deux.'] },
  'cottage-smoothie-bowl-kiwi': { name: 'Bol de fromage blanc au kiwi et aux graines de chia', ing: ['Fromage blanc 2 % — 150 g', 'Kiwi — 1', 'Fruits rouges — 50 g', 'Graines de chia — 10 g', 'Édulcorant — selon le goût'], steps: ['Mixe le fromage blanc avec l’édulcorant jusqu’à obtenir une texture crémeuse.', 'Verse dans un bol et décore avec le kiwi coupé et les fruits rouges.', 'Parsème de graines de chia et mange tout de suite.'] },
  'zucchini-oat-fritters': { name: 'Beignets de courgette et flocons d’avoine', ing: ['Courgette — 200 g', 'Flocons d’avoine — 30 g', 'Œuf — 1', 'Fromage à pâte dure — 20 g', 'Yaourt grec — 50 g', 'Sel, ail'], steps: ['Râpe la courgette, sale-la et presse-la pour retirer l’excès d’eau.', 'Mélange avec les flocons d’avoine, l’œuf, le fromage râpé et l’ail.', 'Fais cuire les beignets dans une poêle sèche, 3 minutes de chaque côté, et sers avec le yaourt.'] },
  'omelette-turkey-lavash': { name: 'Roulé d’omelette à la dinde dans du pain lavash', ing: ['Œuf — 1', 'Blancs d’œufs — 3', 'Jambon de dinde — 50 g', 'Pain lavash fin — 30 g', 'Épinards — 20 g', 'Tomate — 40 g'], steps: ['Bats l’œuf avec les blancs, sale et fais cuire une omelette fine.', 'Dépose sur le lavash le jambon, les épinards, la tomate et l’omelette.', 'Roule bien serré, coupe en deux et fais dorer 1 minute.'] },
  'overnight-oats-pb': { name: 'Overnight oats au beurre de cacahuète', ing: ['Flocons d’avoine — 80 g', 'Lait 2,5 % — 250 ml', 'Banane — 1', 'Beurre de cacahuète — 1 c. à s.', 'Cannelle — 1 pincée'], steps: ['Le soir, verse le lait sur les flocons d’avoine dans un bocal et mélange bien.', 'Place au réfrigérateur pendant 6 à 8 heures.', 'Le matin, ajoute la banane en rondelles et le beurre de cacahuète, puis saupoudre de cannelle.'] },
  'muesli-yogurt-almond': { name: 'Yaourt grec avec muesli et amandes', ing: ['Yaourt grec 5 % — 200 g', 'Muesli sans sucre — 50 g', 'Amandes — 10 g', 'Pomme — 80 g'], steps: ['Verse le yaourt dans un bol.', 'Ajoute le muesli, les amandes concassées et la pomme coupée en dés.', 'Mélange et mange tout de suite, tant que le muesli est croustillant.'] },
  'potato-pancakes-turkey': { name: 'Galettes de pommes de terre avec filet de dinde', ing: ['Pommes de terre — 250 g', 'Œuf — 1', 'Farine — 1 c. à s.', 'Filet de dinde — 100 g', 'Huile — 1 c. à c.', 'Crème aigre 10 % — 30 g'], steps: ['Râpe les pommes de terre, presse-les pour retirer le jus, puis ajoute l’œuf, la farine et le sel.', 'Fais cuire les galettes dans l’huile 3 à 4 minutes de chaque côté, jusqu’à ce qu’elles soient dorées.', 'À part, fais dorer le filet de dinde, coupe-le et sers avec les galettes et la crème aigre.'] },
  'borscht-beef-beans': { name: 'Bortsch au bœuf et aux haricots', ing: ['Bœuf maigre — 100 g', 'Betterave — 100 g', 'Chou — 100 g', 'Pomme de terre — 100 g', 'Haricots blancs en conserve — 80 g', 'Carotte — 50 g', 'Concentré de tomate — 1 c. à s., huile — 1 c. à c.'], steps: ['Fais cuire le bœuf 40 minutes dans 1 l d’eau et écume.', 'Ajoute la pomme de terre, puis le chou, puis la betterave, la carotte et le concentré de tomate revenus dans l’huile.', 'Au bout de 10 minutes, ajoute les haricots, le sel et une feuille de laurier, et laisse reposer sous couvercle.'] },
  'herring-beet-salad': { name: 'Salade de hareng, betterave et pommes de terre', ing: ['Filet de hareng peu salé — 80 g', 'Betterave cuite — 150 g', 'Pommes de terre cuites — 150 g', 'Oignon rouge — 30 g', 'Huile — 1 c. à c.'], steps: ['Coupe les pommes de terre, la betterave et le hareng en dés.', 'Ajoute l’oignon émincé finement.', 'Assaisonne avec l’huile et mélange délicatement pour que la betterave ne colore pas tout.'] },
  'hake-bulgur-veg': { name: 'Colin avec boulgour et légumes', ing: ['Filet de colin — 200 g', 'Boulgour — 40 g (cru)', 'Carotte — 50 g', 'Tomate — 100 g', 'Huile — 1 c. à c.', 'Citron, sel, poivre'], steps: ['Fais cuire le boulgour dans deux fois son volume d’eau pendant 12 minutes.', 'Fais revenir la carotte, ajoute la tomate, dépose le colin, arrose de citron et laisse mijoter à couvert 8 minutes.', 'Sers le poisson avec les légumes sur le boulgour.'] },
  'mackerel-potato-bake': { name: 'Maquereau au four avec pommes de terre et oignon', ing: ['Maquereau (filets) — 150 g', 'Pommes de terre — 200 g', 'Oignon — 50 g', 'Citron — ¼', 'Ail, sel, poivre'], steps: ['Coupe les pommes de terre en quartiers et fais-les cuire 15 minutes à 200 °C.', 'Ajoute l’oignon et le maquereau, arrose de citron, sale et poivre.', 'Poursuis la cuisson 15 minutes, jusqu’à ce que la peau soit dorée.'] },
  'liver-buckwheat': { name: 'Foies de volaille à l’oignon avec du sarrasin', ing: ['Foies de volaille — 200 g', 'Oignon — 60 g', 'Sarrasin — 70 g (cru)', 'Huile — 1 c. à c.', 'Crème aigre 10 % — 15 g'], steps: ['Fais cuire le sarrasin.', 'Fais dorer l’oignon dans l’huile, ajoute les foies et fais-les cuire 7 minutes, puis sale.', 'Ajoute la crème aigre, réchauffe 1 minute et sers avec le sarrasin.'] },
  'turkey-bean-chili': { name: 'Chili de dinde aux haricots', ing: ['Dinde hachée — 180 g', 'Haricots rouges en conserve — 120 g', 'Tomates au naturel — 200 g', 'Poivron — 80 g', 'Oignon — 50 g', 'Riz — 40 g (cru)', 'Huile — 1 c. à c., piment, cumin'], steps: ['Fais cuire le riz. Fais revenir l’oignon et le poivron dans l’huile 3 minutes.', 'Ajoute la viande hachée et fais cuire 6 minutes, puis les tomates, les haricots et les épices.', 'Laisse mijoter 15 minutes à couvert et sers sur le riz.'] },
  'stuffed-peppers-turkey': { name: 'Poivrons farcis à la dinde et au riz', ing: ['Poivrons — 2 moyens (250 g)', 'Dinde hachée — 150 g', 'Riz — 30 g (cru)', 'Sauce tomate — 100 g', 'Oignon — 30 g'], steps: ['Fais précuire le riz 8 minutes. Mélange-le avec la viande, l’oignon et le sel.', 'Farcis les poivrons, place-les dans un plat et nappe de sauce tomate allongée d’eau.', 'Fais cuire au four sous une feuille d’aluminium 35 minutes à 190 °C.'] },
  'lazy-cabbage-rolls': { name: 'Chou farci « paresseux » au bœuf', ing: ['Bœuf haché maigre — 150 g', 'Chou — 200 g', 'Riz — 25 g (cru)', 'Sauce tomate — 100 g', 'Oignon — 30 g'], steps: ['Émince finement le chou et blanchis-le 3 minutes ; fais précuire le riz.', 'Mélange avec la viande et l’oignon, façonne des galettes et dispose-les dans un plat.', 'Nappe de sauce tomate et fais cuire 30 minutes à 180 °C.'] },
  'tuna-tomato-pasta': { name: 'Pâtes au thon et aux tomates cerises', ing: ['Pâtes de blé dur — 120 g (crues)', 'Thon au naturel — 120 g (1 boîte)', 'Tomates cerises — 150 g', 'Ail — 1 gousse', 'Huile d’olive — 1 c. à c.', 'Basilic, poivre'], steps: ['Fais cuire les pâtes al dente.', 'Fais revenir l’ail, ajoute les tomates cerises coupées et laisse mijoter 5 minutes.', 'Ajoute le thon, mélange avec les pâtes et parsème de basilic.'] },
  'turkey-tacos-lavash': { name: 'Tacos de lavash à la dinde hachée', ing: ['Pain lavash fin — 60 g', 'Dinde hachée — 120 g', 'Chou — 50 g', 'Tomate — 60 g', 'Yaourt grec — 30 g', 'Poivron — 40 g', 'Paprika, cumin'], steps: ['Fais revenir la viande avec les épices pendant 7 minutes.', 'Coupe le chou, la tomate et le poivron en fines lanières.', 'Dépose sur le lavash la viande, les légumes et une sauce au yaourt, puis roule en forme de taco.'] },
  'pork-goulash-mash': { name: 'Goulache de porc avec purée de pommes de terre', ing: ['Filet mignon de porc — 150 g', 'Pommes de terre — 250 g', 'Oignon et carotte — 60 g', 'Concentré de tomate — 1 c. à s.', 'Lait — 50 ml', 'Beurre — 5 g, huile — 1 c. à c.'], steps: ['Coupe la viande en dés et fais-la dorer dans l’huile, ajoute l’oignon, la carotte et le concentré de tomate.', 'Couvre d’eau et laisse mijoter 35 minutes jusqu’à ce que la viande soit tendre.', 'Fais cuire les pommes de terre et écrase-les avec le lait et le beurre. Sers le goulache avec la purée.'] },
  'salmon-rice-avocado-bowl': { name: 'Bowl au saumon, riz et avocat', ing: ['Filet de saumon — 130 g', 'Riz — 80 g (cru)', 'Avocat — 70 g', 'Concombre — 80 g', 'Sauce soja — 1 c. à s.', 'Sésame — 5 g'], steps: ['Fais cuire le riz et le saumon au four 12 minutes à 200 °C.', 'Coupe l’avocat et le concombre.', 'Dispose dans un bol le riz, le saumon et les légumes, arrose de sauce soja et parsème de sésame.'] },
  'turkey-burger-wholegrain': { name: 'Burger de dinde dans un pain complet', ing: ['Pain à burger complet — 70 g', 'Dinde hachée — 150 g', 'Fromage à pâte dure — 20 g', 'Tomate — 40 g', 'Feuilles de salade', 'Moutarde, huile — 1 c. à c.'], steps: ['Façonne un steak avec la viande, sale et fais-le dorer 4 minutes de chaque côté.', 'Fais griller le pain à la poêle.', 'Monte le burger : sauce, salade, steak, fromage, tomate.'] },
  'chicken-caesar-light': { name: 'Salade César légère au poulet', ing: ['Blanc de poulet — 150 g', 'Salade romaine ou iceberg — 100 g', 'Parmesan — 15 g', 'Pain complet — 20 g', 'Yaourt grec — 30 g', 'Citron, ail, huile — 1 c. à c.'], steps: ['Fais dorer le blanc de poulet et coupe-le en lanières.', 'Fais griller les dés de pain au four 5 minutes.', 'Mélange le yaourt, l’ail et le jus de citron. Assaisonne la salade, ajoute le poulet, les croûtons et le parmesan.'] },
  'broccoli-chicken-soup': { name: 'Velouté de brocoli au poulet', ing: ['Brocoli — 250 g', 'Blanc de poulet — 120 g', 'Pomme de terre — 100 g', 'Oignon — 30 g', 'Huile — 1 c. à c.', 'Sel, noix de muscade'], steps: ['Fais cuire le blanc de poulet à part et coupe-le en dés.', 'Fais cuire le brocoli, la pomme de terre et l’oignon dans 500 ml d’eau pendant 15 minutes.', 'Mixe pour obtenir un velouté, ajoute le poulet et réchauffe.'] },
  'chicken-vermicelli-soup': { name: 'Soupe de poulet aux vermicelles', ing: ['Blanc de poulet — 120 g', 'Vermicelles fins — 30 g', 'Pomme de terre — 100 g', 'Carotte — 50 g', 'Oignon — 30 g', 'Herbes fraîches, feuille de laurier'], steps: ['Fais cuire le blanc de poulet avec l’oignon 20 minutes dans 700 ml d’eau.', 'Ajoute la pomme de terre et la carotte, et poursuis la cuisson 10 minutes.', 'À la fin, ajoute les vermicelles pour 3 minutes, sale et ajoute les herbes.'] },
  'pilaf-chicken-thigh': { name: 'Pilaf au haut de cuisse de poulet', ing: ['Riz — 90 g (cru)', 'Haut de cuisse de poulet sans peau — 180 g', 'Carotte — 80 g', 'Oignon — 50 g', 'Huile — 1 c. à s.', 'Ail, cumin, curcuma'], steps: ['Fais revenir dans l’huile l’oignon, la carotte et le poulet coupé pendant 8 minutes.', 'Ajoute le cumin, le curcuma, le sel et le riz rincé.', 'Couvre d’eau jusqu’à 1,5 cm au-dessus du riz et laisse cuire à couvert 20 minutes sans remuer.'] },
  'chicken-zucchini-mozzarella': { name: 'Poulet à la courgette et à la mozzarella', ing: ['Blanc de poulet — 200 g', 'Courgette — 150 g', 'Tomate — 100 g', 'Mozzarella allégée — 40 g', 'Huile — 1 c. à c.', 'Origan, sel, poivre'], steps: ['Dispose dans un plat le poulet, la courgette et la tomate coupés, et arrose d’huile.', 'Sale, poivre et saupoudre d’origan.', 'Fais cuire 20 minutes à 190 °C, ajoute la mozzarella dessus et poursuis 5 minutes.'] },
  'vegetable-stew-beans-egg': { name: 'Ragoût de légumes aux haricots blancs et à l’œuf', ing: ['Haricots blancs en conserve — 150 g', 'Courgette — 150 g', 'Poivron — 100 g', 'Tomates — 150 g', 'Oignon — 40 g', 'Œufs — 2', 'Huile — 1 c. à c.'], steps: ['Fais revenir l’oignon et le poivron 3 minutes, ajoute la courgette, les tomates et les haricots.', 'Laisse mijoter 12 minutes, sale et ajoute les épices.', 'Casse les œufs dans le ragoût et couvre 4 minutes.'] },
  'chickpea-spinach-feta': { name: 'Pois chiches aux épinards et à la feta', ing: ['Pois chiches en conserve — 150 g', 'Épinards — 100 g', 'Tomates — 150 g', 'Oignon — 40 g', 'Feta — 30 g', 'Huile — 1 c. à c., ail, cumin'], steps: ['Fais revenir l’oignon avec l’ail et le cumin 2 minutes.', 'Ajoute les tomates et les pois chiches, et laisse mijoter 8 minutes.', 'Incorpore les épinards pendant 2 minutes et émiette la feta dessus.'] },
  'chicken-rice-casserole': { name: 'Gratin de riz au poulet et au fromage', ing: ['Riz — 80 g (cru)', 'Blanc de poulet — 150 g', 'Fromage à pâte dure — 30 g', 'Œuf — 1', 'Lait — 100 ml', 'Courgette — 100 g'], steps: ['Fais précuire le riz. Coupe le poulet et la courgette en dés.', 'Mélange avec le riz et nappe de l’œuf battu avec le lait.', 'Parsème de fromage râpé et fais cuire 25 minutes à 190 °C.'] },
  'hake-lemon-broccoli': { name: 'Colin au four, citron et brocoli', ing: ['Filet de colin — 250 g', 'Brocoli — 200 g', 'Huile — 1 c. à c.', 'Citron — ½', 'Ail, sel, poivre'], steps: ['Dispose le poisson et le brocoli sur la plaque, et arrose d’huile et de jus de citron.', 'Ajoute l’ail haché, sale et poivre.', 'Fais cuire 18 minutes à 200 °C.'] },
  'chicken-thighs-potato-sleeve': { name: 'Hauts de cuisse de poulet et pommes de terre en sachet de cuisson', ing: ['Haut de cuisse de poulet sans peau — 180 g', 'Pommes de terre — 250 g', 'Carotte — 50 g', 'Oignon — 40 g', 'Huile — 1 c. à c.', 'Paprika, ail, sel'], steps: ['Mélange le poulet avec les épices, l’huile et l’ail émincé.', 'Place-le dans un sachet de cuisson avec les pommes de terre, la carotte et l’oignon.', 'Fais cuire 45 minutes à 190 °C, ouvre le sachet et laisse dorer 5 minutes.'] },
  'bean-chicken-corn-salad': { name: 'Salade de haricots, poulet et maïs', ing: ['Blanc de poulet — 120 g', 'Haricots rouges en conserve — 100 g', 'Maïs en conserve — 50 g', 'Poivron — 80 g', 'Yaourt grec — 30 g', 'Feuilles de salade, citron'], steps: ['Fais cuire ou dorer le blanc de poulet et coupe-le en dés.', 'Mélange avec les haricots, le maïs, le poivron coupé et les feuilles de salade.', 'Assaisonne avec le yaourt, le jus de citron et le sel.'] },
  'hake-millet-soup': { name: 'Soupe de colin au millet', ing: ['Filet de colin — 150 g', 'Pommes de terre — 150 g', 'Carotte — 50 g', 'Oignon — 30 g', 'Millet — 20 g (cru)', 'Feuille de laurier, aneth'], steps: ['Porte à ébullition 700 ml d’eau, ajoute le millet, les pommes de terre et la carotte, et fais cuire 12 minutes.', 'Ajoute l’oignon et le colin coupé, et poursuis 8 minutes.', 'Sale et ajoute le laurier et l’aneth.'] },
  'pasta-flotski-turkey': { name: 'Pâtes « po-flotski » à la dinde (pâtes à la viande)', ing: ['Pâtes de blé dur — 100 g (crues)', 'Dinde hachée — 150 g', 'Oignon — 40 g', 'Huile — 1 c. à c.', 'Sel, poivre, herbes fraîches'], steps: ['Fais cuire les pâtes al dente.', 'Fais revenir l’oignon dans l’huile, ajoute la viande et fais cuire 8 minutes avec sel et poivre.', 'Mélange avec les pâtes et parsème d’herbes.'] },
  'beef-green-beans': { name: 'Bœuf aux haricots verts et pommes de terre', ing: ['Bœuf maigre — 150 g', 'Haricots verts — 200 g', 'Pommes de terre — 150 g', 'Oignon — 40 g', 'Huile — 1 c. à c.', 'Poivre noir, feuille de laurier'], steps: ['Coupe la viande en dés et fais-la dorer 5 minutes avec l’oignon.', 'Couvre d’eau et laisse mijoter 20 minutes.', 'Ajoute les pommes de terre et les haricots, et poursuis 12 minutes jusqu’à ce qu’ils soient tendres.'] },
  'turkey-meatball-soup': { name: 'Soupe aux boulettes de dinde', ing: ['Dinde hachée — 120 g', 'Pomme de terre — 100 g', 'Carotte — 50 g', 'Vermicelles fins — 15 g', 'Oignon — 30 g', 'Herbes fraîches, feuille de laurier'], steps: ['Mélange la viande avec l’oignon finement haché et façonne de petites boulettes.', 'Porte à ébullition 600 ml d’eau, ajoute la pomme de terre et la carotte, et fais cuire 10 minutes.', 'Ajoute les boulettes et les vermicelles pour 8 minutes, et parsème d’herbes.'] },
  'rye-crisps-cottage-cucumber': { name: 'Pains croustillants de seigle au fromage blanc, concombre et herbes', ing: ['Fromage blanc 2 % — 150 g', 'Pains croustillants de seigle — 2', 'Concombre — 100 g', 'Aneth, ail, sel'], steps: ['Mélange le fromage blanc avec l’aneth haché, l’ail et le sel.', 'Étale sur les pains croustillants.', 'Dispose dessus des rondelles de concombre et poivre.'] },
  'crispy-chickpeas': { name: 'Pois chiches croustillants au four', ing: ['Pois chiches en conserve — 150 g', 'Huile — 1 c. à c.', 'Paprika fumé — ½ c. à c.', 'Sel, ail en poudre'], steps: ['Rince les pois chiches et sèche-les soigneusement avec un torchon.', 'Mélange-les avec l’huile et les épices, et étale-les sur la plaque.', 'Fais cuire 20 minutes à 200 °C en remuant à mi-cuisson.'] },
  'tuna-egg-sandwich': { name: 'Sandwich au thon et à l’œuf', ing: ['Pain complet — 3 tranches', 'Thon au naturel — 80 g', 'Œuf — 1', 'Concombre — 50 g', 'Yaourt grec — 1 c. à s.'], steps: ['Fais cuire l’œuf dur et écrase-le avec le thon et le yaourt.', 'Étale la préparation sur le pain.', 'Ajoute des rondelles de concombre et couvre avec une autre tranche.'] },
  'turkey-cheese-rolls': { name: 'Roulés de dinde, fromage et concombre', ing: ['Jambon de dinde — 80 g', 'Fromage frais léger — 40 g', 'Concombre — 60 g', 'Herbes fraîches, poivre'], steps: ['Étale une fine couche de fromage sur le jambon.', 'Dépose un bâtonnet de concombre avec les herbes et roule.', 'Coupe en deux et sers frais.'] },
  'nuts-raisins-mix': { name: 'Mélange de noix et de raisins secs', ing: ['Amandes — 20 g', 'Noix — 10 g', 'Raisins secs — 20 g', 'Petite boîte ou petit sachet'], steps: ['Pèse les noix et les raisins secs sur la balance de cuisine.', 'Mélange le tout dans la boîte.', 'Emporte-la avec toi : c’est une portion, pas tout le paquet.'] },
  'banana-oat-peanut-cookies': { name: 'Cookies à l’avoine, à la banane et aux cacahuètes (2 pièces)', ing: ['Flocons d’avoine — 40 g', 'Banane — 80 g', 'Beurre de cacahuète — 1 c. à s.', 'Cannelle — 1 pincée'], steps: ['Écrase la banane, ajoute les flocons, le beurre de cacahuète et la cannelle.', 'Façonne 2 cookies et dépose-les sur du papier cuisson.', 'Fais cuire 15 minutes à 180 °C.'] },
  'baked-apple-cottage': { name: 'Pomme au four au fromage blanc et à la cannelle', ing: ['Pomme — 150 g', 'Fromage blanc 2 % — 100 g', 'Miel — 1 c. à c.', 'Cannelle — ½ c. à c.'], steps: ['Évide la pomme.', 'Garnis-la du mélange de fromage blanc, de miel et de cannelle.', 'Fais cuire 20 minutes à 180 °C.'] },
  'tomato-mozzarella-bruschetta': { name: 'Bruschettas tomate-mozzarella', ing: ['Pain complet — 2 tranches', 'Tomate — 80 g', 'Mozzarella — 40 g', 'Huile d’olive — 1 c. à c.', 'Basilic, ail'], steps: ['Fais griller le pain dans une poêle sèche et frotte-le avec l’ail.', 'Dispose dessus des tranches de tomate et de mozzarella.', 'Arrose d’huile, parsème de basilic et poivre.'] },
  'yogurt-granola-walnut': { name: 'Yaourt au granola, aux noix et au miel', ing: ['Yaourt grec 5 % — 200 g', 'Granola sans sucre — 40 g', 'Noix — 10 g', 'Miel — 1 c. à c.'], steps: ['Verse le yaourt dans un verre ou un bol.', 'Ajoute le granola et les noix concassées.', 'Arrose de miel.'] },
  'tuna-cucumber-boats': { name: 'Barquettes de concombre au thon', ing: ['Concombre — 1 gros (200 g)', 'Thon au naturel — 100 g (égoutté)', 'Yaourt grec — 1 c. à s.', 'Jus de citron, poivre'], steps: ['Coupe le concombre en deux dans la longueur et retire le cœur à la cuillère.', 'Mélange le thon avec le yaourt, le jus de citron et le poivre.', 'Garnis les barquettes et sers tout de suite.'] },
  'rye-avocado-salmon': { name: 'Pains croustillants de seigle à l’avocat et au saumon', ing: ['Pains croustillants de seigle — 3', 'Avocat — 50 g', 'Saumon peu salé — 40 g', 'Jus de citron, herbes fraîches'], steps: ['Écrase l’avocat avec le jus de citron.', 'Étale sur les pains croustillants et dépose de fines tranches de saumon.', 'Décore d’herbes.'] },
  'kefir-bran-berries': { name: 'Képhir au son et aux fruits rouges', ing: ['Képhir 1 % — 250 ml', 'Son d’avoine — 15 g', 'Fruits rouges — 80 g', 'Cannelle — 1 pincée'], steps: ['Verse le képhir sur le son.', 'Laisse gonfler 5 minutes.', 'Ajoute les fruits rouges, saupoudre de cannelle et mélange.'] },
  'chicken-cheese-quesadilla': { name: 'Quesadilla au poulet et au fromage', ing: ['Tortilla — 1 (60 g)', 'Blanc de poulet — 80 g', 'Fromage à pâte dure — 30 g', 'Poivron — 30 g', 'Paprika'], steps: ['Fais dorer le poulet coupé avec le paprika.', 'Dépose sur une moitié de la tortilla le poulet, le poivron et le fromage, et rabats l’autre moitié.', 'Fais dorer dans une poêle sèche 2 minutes de chaque côté.'] },
  'apple-peanut-butter': { name: 'Pomme au beurre de cacahuète', ing: ['Pomme — 180 g', 'Beurre de cacahuète — 1 c. à s.', 'Cannelle — 1 pincée', 'Jus de citron — quelques gouttes'], steps: ['Coupe la pomme en quartiers et arrose de jus de citron pour qu’elle ne noircisse pas.', 'Saupoudre de cannelle.', 'Sers avec le beurre de cacahuète pour tremper.'] },
  'shake-choc-banana-oat': { name: 'Shake chocolat, banane et flocons d’avoine', ing: ['Lait 2,5 % — 300 ml', 'Banane — 1', 'Flocons d’avoine — 30 g', 'Protéine chocolat — 1 dosette (30 g)', 'Cacao — 1 c. à c.'], steps: ['Mets tout dans le blender.', 'Mixe 40 secondes jusqu’à obtenir une texture homogène.', 'Bois-le juste après l’entraînement.'] },
  'shake-peanut-honey': { name: 'Shake au beurre de cacahuète et au miel', ing: ['Lait 2,5 % — 300 ml', 'Beurre de cacahuète — 1,5 c. à s.', 'Banane — 1', 'Protéine vanille — 1 dosette (30 g)', 'Miel — 1 c. à c.'], steps: ['Mets tout dans le blender.', 'Mixe 30 à 40 secondes.', 'Bois-le tout de suite : il est calorique, idéal pour prendre de la masse.'] },
  'shake-cottage-berry-gainer': { name: 'Gainer au fromage blanc et aux fruits rouges', ing: ['Fromage blanc 5 % — 150 g', 'Lait 2,5 % — 200 ml', 'Flocons d’avoine — 40 g', 'Fruits rouges — 100 g', 'Miel — 1 c. à s.'], steps: ['Laisse tremper les flocons d’avoine dans le lait 5 minutes.', 'Ajoute le fromage blanc, les fruits rouges et le miel dans le blender avec le lait et l’avoine.', 'Mixe une minute jusqu’à obtenir une texture lisse.'] },
  'mug-cake-protein': { name: 'Mug cake protéiné', ing: ['Farine d’avoine — 40 g', 'Banane — 100 g', 'Œuf — 1', 'Protéine — ½ dosette (15 g)', 'Cacao — 1 c. à c.', 'Levure chimique — 1 pincée'], steps: ['Écrase la banane dans un grand mug, ajoute l’œuf, la farine, la protéine, le cacao et la levure.', 'Mélange bien.', 'Fais chauffer au micro-ondes 2 minutes à 800 W et laisse reposer 1 minute.'] },
  'shake-peach-yogurt-oat': { name: 'Shake au yaourt, à la pêche et à l’avoine', ing: ['Yaourt grec 2 % — 200 g', 'Pêche — 150 g', 'Flocons d’avoine — 30 g', 'Lait — 150 ml', 'Miel — 1 c. à c.'], steps: ['Mets tout dans le blender.', 'Mixe jusqu’à obtenir une texture crémeuse et homogène.', 'Verse dans un verre et sers bien frais.'] },
  'shake-strawberry-protein': { name: 'Shake protéiné à la fraise', ing: ['Lait d’amande sans sucre — 250 ml', 'Fraises — 150 g', 'Protéine vanille — 1 dosette (30 g)', 'Glaçons — quelques-uns'], steps: ['Mets tout dans le blender.', 'Mixe 30 secondes jusqu’à obtenir une texture homogène.', 'Verse dans un verre et bois tout de suite.'] },
  'shake-coffee-frappe': { name: 'Frappé protéiné au café', ing: ['Espresso — 60 ml', 'Lait 1,5 % — 200 ml', 'Protéine chocolat — 1 dosette (30 g)', 'Glaçons — 4 à 5', 'Cannelle'], steps: ['Laisse refroidir l’espresso.', 'Mixe-le au blender avec le lait, la protéine et les glaçons.', 'Verse dans un verre et saupoudre de cannelle.'] },
  'cottage-ice-cream-berries': { name: 'Glace au fromage blanc et aux fruits rouges', ing: ['Fromage blanc 2 % — 200 g', 'Fruits rouges surgelés — 100 g', 'Édulcorant — selon le goût', 'Vanille — 1 c. à c.'], steps: ['Mixe le tout au blender jusqu’à obtenir une préparation épaisse.', 'Verse dans une boîte et place au congélateur 30 minutes.', 'Sers en boules.'] },
  'yogurt-cocoa-mousse': { name: 'Mousse au yaourt et au cacao', ing: ['Yaourt grec 2 % — 250 g', 'Protéine chocolat — ½ dosette (15 g)', 'Cacao — 1 c. à s.', 'Édulcorant'], steps: ['Fouette le yaourt avec le cacao, la protéine et l’édulcorant jusqu’à ce qu’il soit mousseux.', 'Répartis dans des verres.', 'Mets au frais 30 minutes.'] },
  'shake-banana-spinach-kefir': { name: 'Smoothie banane, épinards et képhir', ing: ['Képhir 1 % — 250 ml', 'Banane — 100 g', 'Épinards — 30 g', 'Flocons d’avoine — 20 g'], steps: ['Mets tout dans le blender.', 'Mixe 30 à 40 secondes jusqu’à obtenir une texture homogène.', 'Bois-le tout de suite, avant qu’il ne se sépare.'] },
  'mango-coconut-smoothie': { name: 'Smoothie mangue-coco', ing: ['Mangue (surgelée) — 150 g', 'Lait de coco allégé — 100 ml', 'Yaourt grec — 100 g', 'Jus de citron vert — 1 c. à c.'], steps: ['Mets tous les ingrédients dans le blender.', 'Mixe 30 à 40 secondes jusqu’à ce que ce soit épais.', 'Verse dans un verre et bois tout de suite.'] },
  'ryazhenka-berry-smoothie': { name: 'Smoothie de ryazhenka aux fruits rouges', ing: ['Ryazhenka (lait cuit fermenté) 2,5 % — 250 ml', 'Fruits rouges — 100 g', 'Banane — 80 g', 'Flocons d’avoine — 15 g'], steps: ['Mets tout dans le blender.', 'Mixe 30 secondes.', 'Sers bien frais.'] },
  'yogurt-berry-jelly': { name: 'Gelée de yaourt aux fruits rouges', ing: ['Yaourt grec — 150 g', 'Gélatine — 10 g', 'Fruits rouges — 100 g', 'Édulcorant', 'Eau chaude — 50 ml'], steps: ['Dissous la gélatine dans l’eau chaude.', 'Mélange avec le yaourt et l’édulcorant.', 'Répartis les fruits rouges dans des verres, verse la préparation et mets au frais 2 heures.'] },
  'frozen-banana-cocoa-ice': { name: 'Glace banane-cacao', ing: ['Banane congelée — 150 g', 'Fromage blanc 2 % — 100 g', 'Cacao — 1 c. à c.', 'Édulcorant — selon le goût'], steps: ['Coupe la banane en rondelles et congèle-la à l’avance.', 'Mixe avec le fromage blanc, le cacao et l’édulcorant jusqu’à obtenir une texture de crème glacée.', 'Sers tout de suite ou remets au congélateur 20 minutes.'] },
  'protein-waffles-cottage': { name: 'Gaufres protéinées au fromage blanc', ing: ['Fromage blanc 2 % — 120 g', 'Flocons d’avoine — 40 g', 'Œuf — 1', 'Levure chimique — ½ c. à c.', 'Vanille en poudre, édulcorant — selon le goût', 'Yaourt grec — 40 g (pour servir)', 'Fruits rouges — 50 g'], steps: ['Mixe les flocons en farine, puis mélange-les avec le fromage blanc, l’œuf, la levure, la vanille et l’édulcorant jusqu’à obtenir une pâte épaisse.', 'Fais chauffer le gaufrier, graisse-le légèrement et fais cuire deux gaufres de 4 à 5 minutes chacune, jusqu’à ce qu’elles soient bien dorées. Sans gaufrier, fais cuire de petits pancakes dans une poêle antiadhésive.', 'Sers avec le yaourt grec et les fruits rouges.'] },
  'baked-pancake-yogurt': { name: 'Pancake au four, yaourt et fruits rouges', ing: ['Yaourt grec — 120 g', 'Œuf — 1', 'Blanc d’œuf — 1', 'Farine de blé ou d’avoine — 30 g', 'Levure chimique — ½ c. à c.', 'Fruits rouges — 80 g', 'Édulcorant, vanille en poudre — selon le goût'], steps: ['Préchauffe le four à 180 °C. Mélange le yaourt, l’œuf, le blanc, la farine, la levure, l’édulcorant et la vanille jusqu’à obtenir la consistance d’une crème épaisse.', 'Verse la pâte dans un petit moule beurré et dispose la moitié des fruits rouges dessus.', 'Fais cuire 18 à 20 minutes, jusqu’à ce que le pancake gonfle et soit bien doré. Sers avec le reste des fruits rouges.'] },
  'french-toast-cottage': { name: 'Pain perdu fourré au fromage blanc', ing: ['Pain complet — 2 tranches (70 g)', 'Œuf — 1', 'Lait — 40 ml', 'Fromage blanc 2 % — 100 g', 'Miel — 1 c. à c.', 'Huile pour la cuisson — 1 c. à c.', 'Cannelle — 1 pincée'], steps: ['Mélange le fromage blanc avec le miel et la cannelle. Bats l’œuf avec le lait dans une assiette creuse.', 'Étale la garniture au fromage blanc sur une tranche et recouvre avec l’autre pour former un sandwich.', 'Trempe le sandwich des deux côtés dans le mélange aux œufs, puis fais-le dorer dans une poêle chaude 2 à 3 minutes de chaque côté.'] },
  'savory-oat-pancake': { name: 'Galette d’avoine salée au fromage et aux herbes', ing: ['Flocons d’avoine — 50 g', 'Œuf — 1', 'Blanc d’œuf — 1', 'Lait — 50 ml', 'Fromage à pâte dure — 25 g', 'Tomate — 100 g', 'Aneth, sel, poivre'], steps: ['Mélange les flocons avec l’œuf, le blanc, le lait, le sel et le poivre, puis laisse gonfler 5 minutes.', 'Verse la préparation en couche fine dans une poêle antiadhésive chaude, parsème de fromage râpé et d’aneth finement ciselé.', 'Fais cuire à couvert 3 minutes de chaque côté, plie en deux et sers avec la tomate coupée en tranches.'] },
  'banana-bread-protein': { name: 'Banana bread protéiné (1 part sur 6)', ing: ['Bananes bien mûres — 3 (300 g)', 'Farine d’avoine — 120 g', 'Œufs — 2', 'Yaourt grec — 150 g', 'Protéine vanille — 1 dosette (30 g)', 'Miel — 1 c. à s.', 'Myrtilles — 80 g', 'Levure chimique — 2 c. à c., cannelle'], steps: ['Préchauffe le four à 175 °C. Écrase les bananes à la fourchette en purée.', 'Ajoute les œufs, le yaourt et le miel, mélange, puis incorpore la farine, la protéine, la levure et la cannelle. Ajoute délicatement les myrtilles.', 'Verse dans un moule à cake chemisé de papier cuisson et fais cuire 40 à 45 minutes, jusqu’à ce qu’une pique en bois en ressorte sèche.', 'Laisse refroidir 15 minutes dans le moule, puis coupe en 6 parts. Congèle le reste en portions individuelles.'] },
  'garlic-beef-rice': { name: 'Bœuf caramélisé à l’ail et riz', ing: ['Bœuf maigre (filet, épaule) — 150 g', 'Riz — 70 g (cru)', 'Brocoli — 100 g', 'Ail — 3 gousses', 'Sauce soja — 25 ml', 'Miel — 2 c. à c.', 'Fécule — 1 c. à c.', 'Huile — 1 c. à c.'], steps: ['Fais cuire le riz. Coupe le bœuf en fines lanières, dans le sens contraire des fibres, et roule-les dans la fécule.', 'Mélange la sauce soja, le miel, l’ail râpé et 3 c. à s. d’eau.', 'Fais saisir la viande 3 à 4 minutes dans une poêle très chaude, verse la sauce et laisse mijoter 1 à 2 minutes, jusqu’à ce qu’elle épaississe en un glaçage brillant.', 'Cuis le brocoli 3 minutes à la vapeur ou à l’eau bouillante et sers avec le riz. Pour le meal prep, multiplie tout par 4 et répartis dans des boîtes : ça se garde 4 jours au réfrigérateur.'] },
  'chicken-rendang': { name: 'Poulet rendang et riz', ing: ['Haut de cuisse de poulet sans peau ni os — 160 g', 'Lait de coco — 60 ml', 'Riz — 65 g (cru)', 'Oignon — ½', 'Ail — 2 gousses', 'Gingembre — 2 cm', 'Sucre ou miel — 1 c. à c.', 'Curry, cumin, paprika, cannelle, sel ; jus de citron vert'], steps: ['Mixe l’oignon, l’ail et le gingembre en pâte, puis mélange-la avec les épices sèches.', 'Fais revenir la pâte 2 minutes, ajoute le poulet coupé en morceaux et fais-le dorer 3 à 4 minutes.', 'Verse le lait de coco et 100 ml d’eau, ajoute le sucre. Laisse mijoter à feu doux 25 à 30 minutes, jusqu’à ce que la sauce soit foncée, épaisse et bien nappante.', 'Termine avec le jus de citron vert et sers avec du riz cuit.'] },
  'chicken-crust-pizza': { name: 'Pizza à base de poulet', ing: ['Filet de poulet — 150 g', 'Œuf — 1', 'Fromage à pâte dure râpé — 10 g', 'Sauce tomate — 40 g', 'Mozzarella — 50 g', 'Jambon de dinde — 30 g', 'Tomate — 40 g', 'Origan, sel, poivre'], steps: ['Mixe le filet au blender ou au hachoir en une farce lisse, puis mélange avec l’œuf, le fromage, le sel et le poivre.', 'Étale la farce en un disque fin sur du papier cuisson et fais cuire 12 minutes à 200 °C.', 'Nappe la base de sauce tomate, dispose le jambon, la tomate et la mozzarella, puis parsème d’origan.', 'Remets au four 8 à 10 minutes, jusqu’à ce que le fromage fonde et dore.'] },
  'egg-roll-bowl-turkey': { name: 'Egg roll bowl à la dinde', ing: ['Hachis de dinde — 150 g', 'Chou blanc — 200 g', 'Carotte — 1 petite', 'Ail — 1 gousse', 'Gingembre — 1 cm', 'Sauce soja — 20 ml', 'Huile de sésame — 1 c. à c.', 'Graines de sésame — 1 c. à c.'], steps: ['Émince finement le chou en lanières et râpe la carotte avec la grosse râpe.', 'Fais revenir le hachis avec l’ail et le gingembre 5 minutes à feu vif, en émiettant les morceaux.', 'Ajoute le chou et la carotte, verse la sauce soja et l’huile de sésame, puis laisse cuire 5 à 6 minutes pour que les légumes restent un peu croquants.', 'Parsème de graines de sésame. C’est la garniture d’un egg roll, sans la pâte.'] },
  'chicken-teriyaki-bowl': { name: 'Bowl de poulet teriyaki et riz', ing: ['Filet de poulet — 160 g', 'Riz — 70 g (cru)', 'Brocoli — 120 g', 'Sauce soja — 25 ml', 'Miel — 2 c. à c.', 'Ail — 1 gousse', 'Gingembre — 1 cm', 'Fécule — 1 c. à c.', 'Huile — 1 c. à c.', 'Graines de sésame — ½ c. à c.'], steps: ['Fais cuire le riz et blanchis le brocoli 3 minutes dans l’eau bouillante.', 'Pour la sauce, mélange la sauce soja, le miel, l’ail râpé, le gingembre, la fécule et 50 ml d’eau.', 'Coupe le filet en dés et fais-les dorer à l’huile 5 à 6 minutes, puis verse la sauce et laisse cuire jusqu’à ce qu’elle épaississe et enrobe le poulet d’un glaçage brillant.', 'Dispose le riz, le brocoli et le poulet dans un bol et parsème de graines de sésame.'] },
  'zucchini-boats-stuffed': { name: 'Courgettes farcies (barquettes)', ing: ['Courgette — 1 moyenne (350 g)', 'Hachis de dinde — 120 g', 'Oignon — ½', 'Sauce tomate — 50 g', 'Fromage à pâte dure — 30 g', 'Ail — 1 gousse', 'Persil, sel, poivre'], steps: ['Coupe la courgette en deux dans la longueur, évide-la à la cuillère en gardant des parois de 1 cm. Hache finement la chair retirée.', 'Fais revenir l’oignon, l’ail et le hachis avec la chair de courgette 6 à 7 minutes, ajoute la sauce tomate, le sel et le poivre.', 'Remplis les barquettes de farce et parsème de fromage râpé.', 'Fais cuire 25 minutes à 190 °C et sers avec du persil.'] },
  'shrimp-couscous-lemon': { name: 'Couscous aux crevettes et au citron', ing: ['Crevettes décortiquées — 180 g', 'Couscous — 60 g (sec)', 'Tomates cerises — 80 g', 'Concombre — 80 g', 'Huile d’olive — 2 c. à c.', 'Ail — 1 gousse', 'Citron — ½, persil, sel'], steps: ['Verse de l’eau bouillante sur le couscous à volume égal (1 pour 1), couvre 5 minutes et égrène à la fourchette.', 'Fais sauter les crevettes avec l’ail dans la moitié de l’huile 2 à 3 minutes, jusqu’à ce qu’elles rosissent.', 'Mélange le couscous avec les tomates cerises et le concombre coupés, le jus et le zeste du citron et le reste de l’huile.', 'Dépose les crevettes dessus et parsème de persil.'] },
  'protein-bar-homemade': { name: 'Barre protéinée maison (1 sur 6)', ing: ['Flocons d’avoine — 120 g', 'Purée de cacahuètes — 80 g', 'Miel — 50 g', 'Protéine — 2 dosettes (60 g)', 'Lait — 60 ml'], steps: ['Fais chauffer la purée de cacahuètes avec le miel jusqu’à ce qu’elle devienne fluide, puis retire du feu.', 'Mélange les flocons avec la protéine, ajoute la purée et le lait, puis pétris bien.', 'Tasse fermement la préparation dans un moule chemisé de papier cuisson, laisse refroidir 1 heure et coupe en 6 barres.', 'Conserve au réfrigérateur jusqu’à 5 jours.'] },
  'deviled-eggs-tuna': { name: 'Œufs mimosa au thon (2 pièces)', ing: ['Œufs durs — 2', 'Thon au naturel — 30 g', 'Yaourt grec — 20 g', 'Moutarde — ½ c. à c.', 'Aneth, paprika, sel, poivre'], steps: ['Fais cuire les œufs durs (10 minutes), laisse-les refroidir, écale-les et coupe-les en deux dans la longueur.', 'Retire les jaunes et écrase-les à la fourchette avec le thon, le yaourt, la moutarde, le sel et le poivre.', 'Garnis les moitiés de blancs avec la préparation, puis ajoute un peu d’aneth et une pincée de paprika.'] },
  'turkey-tortilla-mini-pizza': { name: 'Mini pizza sur tortilla à la dinde', ing: ['Tortilla — 1 (60 g)', 'Sauce tomate — 40 g', 'Mozzarella — 40 g', 'Jambon de dinde — 40 g', 'Tomate — 40 g', 'Origan'], steps: ['Préchauffe le four à 200 °C. Nappe la tortilla de sauce tomate.', 'Dispose le jambon, de fines rondelles de tomate et la mozzarella, puis parsème d’origan.', 'Fais cuire 8 à 10 minutes, jusqu’à ce que les bords soient croustillants et le fromage fondu.'] },
  'pumpkin-cottage-ice-cream': { name: 'Glace à la citrouille et au fromage blanc', ing: ['Fromage blanc 2 % — 150 g', 'Purée de citrouille — 120 g', 'Miel — 1 c. à c.', 'Cannelle — ½ c. à c.', 'Vanille en poudre — 1 pincée'], steps: ['Mixe le fromage blanc, la purée de citrouille, le miel, la cannelle et la vanille au blender jusqu’à obtenir une crème lisse.', 'Répartis la préparation dans des moules ou dans une boîte et congèle 3 à 4 heures.', 'Avant de servir, laisse reposer 10 minutes à température ambiante et sers à la cuillère.'] },
  'protein-fluff': { name: 'Fluff protéiné', ing: ['Protéine — 1 dosette (30 g)', 'Fruits rouges surgelés — 150 g', 'Eau — 80 ml', 'Jus de citron — 1 c. à c.'], steps: ['Mets la protéine, les fruits rouges à peine décongelés, l’eau et le jus de citron dans un grand bol.', 'Fouette au batteur à vitesse maximale 5 à 7 minutes, jusqu’à ce que la masse double de volume et devienne une mousse épaisse.', 'Mange-le aussitôt à la cuillère, tant qu’il tient bien.'] },
  'tiramisu-cottage': { name: 'Tiramisu au fromage blanc et au café', ing: ['Fromage blanc 2 % — 120 g', 'Yaourt grec — 60 g', 'Biscuits à la cuillère — 2 (25 g)', 'Café fort — 60 ml', 'Cacao — 1 c. à c.', 'Édulcorant, vanille en poudre — selon le goût'], steps: ['Fouette le fromage blanc avec le yaourt, l’édulcorant et la vanille jusqu’à obtenir une texture de crème.', 'Trempe rapidement les biscuits à la cuillère dans le café refroidi et dépose-les au fond d’un verre.', 'Recouvre de crème au fromage blanc, saupoudre de cacao et laisse prendre au frais au moins 1 heure.'] },
  'cookie-dough-protein': { name: 'Pâte à cookie protéinée comestible', ing: ['Farine d’avoine — 25 g', 'Purée de cacahuètes — 15 g', 'Protéine — ⅔ de dosette (20 g)', 'Lait — 40 ml', 'Miel — 1 c. à c.', 'Chocolat noir — 10 g'], steps: ['Mélange la farine avec la protéine.', 'Ajoute la purée de cacahuètes, le miel et le lait petit à petit, puis mélange jusqu’à obtenir une pâte épaisse, comme une pâte à cookies.', 'Incorpore le chocolat haché et mange à la cuillère, ou mets 15 minutes au congélateur.'] },
  'yogurt-berry-bark': { name: 'Écorce de yaourt aux fruits rouges surgelés', ing: ['Yaourt grec — 150 g', 'Fruits rouges — 50 g', 'Amandes — 10 g', 'Miel — 1 c. à c.'], steps: ['Mélange le yaourt avec le miel et étale-le en couche de 5 mm sur du papier cuisson.', 'Enfonce les fruits rouges dans la surface et parsème d’amandes concassées.', 'Congèle 3 heures, casse en morceaux et conserve au congélateur.'] },
};
